<article class="article-page"><header class="article-hero"><div class="container container--md"><div class="breadcrumb"><a href="/articles"><?= e(t('nav.articles')) ?></a><span><?= icon('arrow-left') ?></span><span><?= e($article['type']) ?></span></div><span class="eyebrow">Mentoris Journal</span><h1><?= e($article['title']) ?></h1><p><?= e($article['excerpt']) ?></p><div class="article-meta"><span><?= icon('user') ?> <?= e($article['author']) ?></span><span><?= icon('clock') ?> <?= e($article['read']) ?></span><time class="ltr"><?= e(substr($article['published_at'], 0, 10)) ?></time></div></div></header><?php if (!empty($article['image'])): ?><div class="container container--md article-cover"><img src="<?= asset($article['image']) ?>" alt="<?= e($article['title']) ?>" width="1200" height="720"></div><?php endif; ?><div class="container container--sm article-body"><?= nl2br(e($article['body'])) ?></div></article>
